def f(N: int, M: int, bridges: List[Tuple[int, int, int]]) -> int:
    bridges = list(map(list, bridges))
    graph = [[float('inf')] * N for _ in range(N)]
    for S, D, C in bridges:
        graph[S-1][D-1] = C
        graph[D-1][S-1] = C

    for k in range(N):
        for i in range(N):
            for j in range(N):
                graph[i][j] = min(graph[i][j], graph[i][k] + graph[k][j])
    return max(map(max, graph))
``` 
